import{_ as e,o as a,c as r,a7 as o}from"./chunks/framework.C4ZIv4ii.js";const g=JSON.parse('{"title":"Shipping &amp; Tax","description":"","frontmatter":{},"headers":[],"relativePath":"ecommerce/shipping-tax.md","filePath":"ecommerce/shipping-tax.md","lastUpdated":1786525002000}'),n={name:"ecommerce/shipping-tax.md"};function s(i,t,h,d,c,p){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="shipping-amp-tax" tabindex="-1">Shipping &amp; Tax <a class="header-anchor" href="#shipping-amp-tax" aria-label="Permalink to &quot;Shipping &amp;amp; Tax&quot;">​</a></h1><p>Both live under <strong>Admin → Shop → Settings</strong>, on their own tabs.</p><h2 id="shipping" tabindex="-1">Shipping <a class="header-anchor" href="#shipping" aria-label="Permalink to &quot;Shipping&quot;">​</a></h2><h3 id="flat-rate" tabindex="-1">Flat rate <a class="header-anchor" href="#flat-rate" aria-label="Permalink to &quot;Flat rate&quot;">​</a></h3><p>The simplest setup: one cost for every order, set under <strong>Shipping → Flat rate</strong>. It applies whenever no zone matches the customer&#39;s country.</p><h3 id="free-shipping-threshold" tabindex="-1">Free shipping threshold <a class="header-anchor" href="#free-shipping-threshold" aria-label="Permalink to &quot;Free shipping threshold&quot;">​</a></h3><p><strong>Shipping → Free shipping threshold</strong> makes shipping free once the cart subtotal reaches an amount. Set it to <code>0</code> to switch it off. Zones can carry their own threshold, which takes precedence for customers in that zone.</p><h3 id="local-pickup" tabindex="-1">Local pickup <a class="header-anchor" href="#local-pickup" aria-label="Permalink to &quot;Local pickup&quot;">​</a></h3><p>Enable it and <em>Local pickup</em> appears at checkout at no cost, alongside delivery.</p><h3 id="shipping-zones" tabindex="-1">Shipping zones <a class="header-anchor" href="#shipping-zones" aria-label="Permalink to &quot;Shipping zones&quot;">​</a></h3><p>A zone is a group of countries with their own rates. For each zone you set:</p><table tabindex="0"><thead><tr><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Name</strong></td><td>Shown to the customer as the shipping method label</td></tr><tr><td><strong>Countries</strong></td><td>Which countries the zone covers</td></tr><tr><td><strong>Base shipping cost</strong></td><td>Charged when no band matches</td></tr><tr><td><strong>Free shipping threshold</strong></td><td>Free above this subtotal, for this zone only</td></tr><tr><td><strong>Calculation type</strong></td><td>Flat rate, quantity based, or weight based</td></tr></tbody></table><p>Zones are matched on the customer&#39;s country, falling back to the parent country when the value includes a state (<code>Bangladesh - Dhaka</code> matches a zone listing <code>Bangladesh</code>).</p><h3 id="quantity-based-rates" tabindex="-1">Quantity-based rates <a class="header-anchor" href="#quantity-based-rates" aria-label="Permalink to &quot;Quantity-based rates&quot;">​</a></h3><p>Choose <strong>Quantity Based (Per Item Range)</strong> and add bands:</p><table tabindex="0"><thead><tr><th>Min Qty</th><th>Max Qty</th><th>Cost</th></tr></thead><tbody><tr><td>1</td><td>3</td><td>60</td></tr><tr><td>4</td><td>10</td><td>100</td></tr><tr><td>11</td><td><em>(blank)</em></td><td>150</td></tr></tbody></table><p>Leave <strong>Max</strong> blank for &quot;and above&quot;. A cart matching no band pays the zone&#39;s base cost.</p><h3 id="weight-based-rates" tabindex="-1">Weight-based rates <a class="header-anchor" href="#weight-based-rates" aria-label="Permalink to &quot;Weight-based rates&quot;">​</a></h3><p>Choose <strong>Weight Based (Per Weight Range)</strong> and the same bands are read in your weight unit instead. Weights come from <strong>Product Data → Shipping</strong>; a variation may carry its own and otherwise inherits the product&#39;s. A product with no weight counts as zero rather than blocking the order.</p><table tabindex="0"><thead><tr><th>Min Weight</th><th>Max Weight</th><th>Cost</th></tr></thead><tbody><tr><td>0</td><td>1</td><td>50</td></tr><tr><td>1</td><td>5</td><td>120</td></tr><tr><td>5</td><td><em>(blank)</em></td><td>300</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>A band with a missing or non-numeric cost is skipped rather than treated as free, and the zone&#39;s base cost applies instead. Fill every row you add.</p></div><h3 id="free-shipping-coupons" tabindex="-1">Free shipping coupons <a class="header-anchor" href="#free-shipping-coupons" aria-label="Permalink to &quot;Free shipping coupons&quot;">​</a></h3><p>A <code>free_shipping</code> coupon zeroes every method rather than discounting the goods, so the saving lands on the shipping line. See <a href="/falconcms/ecommerce/coupons.html">Coupons</a>.</p><h2 id="tax" tabindex="-1">Tax <a class="header-anchor" href="#tax" aria-label="Permalink to &quot;Tax&quot;">​</a></h2><p>Tax is off until <strong>General → Enable tax rates and calculations</strong> is ticked. Nothing below has any effect while it is off.</p><h3 id="rates" tabindex="-1">Rates <a class="header-anchor" href="#rates" aria-label="Permalink to &quot;Rates&quot;">​</a></h3><p><strong>Tax → Tax rates</strong> is a table:</p><table tabindex="0"><thead><tr><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Country</strong></td><td>The country the rate applies to, or <code>*</code> for everywhere</td></tr><tr><td><strong>Rate</strong></td><td>Percentage, e.g. <code>15</code></td></tr><tr><td><strong>Name</strong></td><td>The label on the cart line, e.g. <code>VAT</code></td></tr><tr><td><strong>Apply to shipping</strong></td><td>Whether shipping is taxed as well</td></tr></tbody></table><p>Matching runs exact country → parent country → <code>*</code> wildcard, so a specific rate always beats the fallback.</p><h3 id="which-country-is-charged" tabindex="-1">Which country is charged <a class="header-anchor" href="#which-country-is-charged" aria-label="Permalink to &quot;Which country is charged&quot;">​</a></h3><p><strong>Tax → Calculation basis</strong> decides whose country is used:</p><table tabindex="0"><thead><tr><th>Basis</th><th>Meaning</th></tr></thead><tbody><tr><td><code>shipping</code></td><td>Where the order is being delivered</td></tr><tr><td><code>billing</code></td><td>The customer&#39;s billing country</td></tr><tr><td><code>base</code></td><td>Your own shop country, regardless of the customer</td></tr></tbody></table><h3 id="prices-with-or-without-tax" tabindex="-1">Prices with or without tax <a class="header-anchor" href="#prices-with-or-without-tax" aria-label="Permalink to &quot;Prices with or without tax&quot;">​</a></h3><p>Two settings work together, and mixing them is what makes tax visible in the catalogue:</p><table tabindex="0"><thead><tr><th>Setting</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Price entry</strong></td><td>Whether the prices you type already contain tax</td></tr><tr><td><strong>Catalogue display</strong></td><td>Whether shoppers should see prices with tax</td></tr></tbody></table><p>When the two differ, prices are converted on the way out — enter <code>1,000</code> without tax, display with tax, and a 15% rate shows <code>1,150</code>. When they match, nothing is converted.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Per-product override: <strong>Product Data → General → Tax status</strong> can be set to <em>None</em> so a particular product is never taxed.</p></div><h3 id="on-the-cart" tabindex="-1">On the cart <a class="header-anchor" href="#on-the-cart" aria-label="Permalink to &quot;On the cart&quot;">​</a></h3><p>Tax is calculated on the taxable items only, after coupons and promotions have been taken off in proportion, and shipping is added to the base when the rate says to tax it.</p>',39)])])}const u=e(n,[["render",s]]);export{g as __pageData,u as default};
